<template>
  <el-dialog
    :title="title"
    :visible.sync="visible"
    :width="width"
    :center="true"
    :modal="false"
    :fullscreen="isMobile ? true : fullscreen"
    :top="dTop"
    @close="onDialogClose"
    class="marker-dialog-wrapper"
    :class="isMobile ? 'marker-mobile-dialog-wrapper' : ''"
    :destroy-on-close="false"
  >
    <div class="marker-dialog">
      <div class="marker-dialog-body">
        <div
          class="video-marker"
          ref="videoMarker"
          id="iot-camera-dialog-video-marker"
          v-if="result"
        >
          <div class="player" id="ys7-player"></div>
        </div>
        <el-empty description="获取播放地址中..." v-else></el-empty>
      </div>
    </div>
  </el-dialog>
</template>
  <script>
import { isMobile } from '@/utils/tools'
import {
  getCameraLiveUrl,
} from '@/api/iot'
export default {
  name: 'CameraYs7Show',
  data() {
    return {
      markerInfo: null,
      title: '',
      width: '780px',
      visible: false,
      fullscreen: false,
      dTop: '',

      videoUrl: '',
      mode: '4',
      aspect: '16:9',
      muted: false,
      autoplay: false,
      fluent: false,
      stretch: false,
      live: false,
      result: null,
      ys7Player: null,
      leChangePlayer: null,
    }
  },
  computed: {
    isMobile() {
      return isMobile()
    },
  },
  methods: {
    async open(
      markerInfo,
      dialogWidth = '760px',
      fullscreen = false,
      dTop = '1vh'
    ) {
      this.markerInfo = markerInfo
      this.title = markerInfo.title || null
      this.fullscreen = fullscreen
      this.dTop = dTop
      this.width = dialogWidth
      this.visible = true
      if (!this.result) {
        this.result = await getCameraLiveUrl(markerInfo.device_full_id)
        if (!this.result) {
          return false
        }
      }
      this.videoUrl = this.result.url
      this.$nextTick(() => {
        this.initYs7Player()
      })
    },
    initYs7Player() {
      // eslint-disable-next-line no-undef
      this.ys7Player = new EZUIKit.EZUIKitPlayer({
        id: 'ys7-player', // 视频容器ID
        accessToken: this.result.access_token,
        url: this.videoUrl,
        audio: false,
        template: 'standard',
        handleError: (err) => {
          console.error('ys7Player error:', err)
        },
      })
    },
    onPlayError() {},
    onBeforeDialogClose() {
      this.videoUrl = ''
      if (this.ys7Player) {
        this.ys7Player.stop()
        this.ys7Player.destroy()
        this.ys7Player = null
        document.getElementById('ys7-player').innerHTML = ''
      }
      return true
    },
    onDialogClose() {
      this.onBeforeDialogClose()
      this.$emit('onDialogClose')
    },
  },
}
</script>
